});

// 2. Route Parameters & Constraints
// 2a. Parameter opsional dengan nilai default "Tamu"
Route::get('/profile/{name?}', function ($name = 'Tamu') {
    return "Halo, " . $name . "!";
});

// 2b. Parameter wajib dengan constraint angka (whereNumber)
Route::get('/product/{id}', function ($id) {
    return "Detail Produk dengan ID: " . $id;
})->whereNumber('id');

// 3. Named Routes (URL /admin/dashboard diberi nama 'dashboard')
Route::get('/admin/dashboard', function () {
    return "<h1>Halaman Dashboard Admin</h1><p>Berhasil diakses menggunakan Named Route.</p>";
})->name('dashboard');

// 4. Route Groups & Prefix (/member)
Route::prefix('member')->group(function () {
    Route::get('/profile', function () {
        return "Profil Member";
    });

    Route::get('/settings', function () {
        return "Pengaturan Member";
    });
});

Route::fallback(function () {
    return "404 - Not Found";
});

route::fallback(function () {
    return "404 - Not Found";
});
